($clean := function($s) {(
  $text := ($contains($s, '<') ? $replace($s, /<[^>]+>/g, function($m) {(
    $tag := $lowercase($m.match);
    $substring($tag,0,4) = '<pre' ? '\n\n```\n' :
    $tag = '</pre>' ? '\n```\n' :
    ($tag = '<p>' or $substring($tag,0,3) = '<p ' or $tag = '</p>' or $substring($tag,0,4) = '</p ') ? '\n\n' : ''
  )}) : $s);
  $contains($text, '&') ? $replace($text, /&(quot|#x27|#39|#039|gt|lt|amp);/ig, function($m) {(
    $entity := $lowercase($m.groups[0]);
    $entity = 'quot' ? '"' :
    ($entity = '#x27' or $entity = '#39' or $entity = '#039') ? "'" :
    $entity = 'gt' ? '>' : $entity = 'lt' ? '<' : $entity = 'amp' ? '&' : $m.match
  )}) : $text
)};
$node := function($c,$depth) {(
  $children := $depth < 4 ? $c.children[author != null and text != null and text != '' and $not($exists(deleted) and deleted = true)] : [];
  {'key':$string($c.id),'name':$c.author,'meta':$exists($c.created_at) ? $replace($substring($c.created_at, 0, 16), 'T', ' ') : '',
   'badges':[],
   'depth':$depth,'body':$clean($c.text),
   'children':$depth < 4 ? $append([], $map($children[[0..7]], function($child) {$node($child,$depth+1)})) : []}
)};
$roots := $data.item.children[author != null and text != null and text != '' and $not($exists(deleted) and deleted = true)][[0..24]];
$story := $data.item.text != null and $data.item.text != '' ? [{'key':'story-body','name':$data.item.author,'meta':'작성자 본문','badges':['작성자 본문'],'depth':0,'body':$clean($data.item.text)}] : [];
$append($story,$append([], $map($roots,function($root){$node($root,0)}))))
